import math

def get_divisors(n):
    divs = []
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
    return sorted(divs)

def solve_problem(N_max=1000):
    solutions = {}
    print(f"Starting search for n up to N={N_max}...")
    for n in range(16, N_max + 1):
        divs = get_divisors(n)

        # Condition: n must have at least 5 positive divisors
        if len(divs) < 5:
            continue

        # Identify a, b, c: 2nd, 3rd, and 5th smallest divisors
        # Divisors are 1-indexed: d1=divs[0], d2=divs[1], d3=divs[2], d4=divs[3], d5=divs[4]
        a = divs[1]
        b = divs[2]
        c = divs[4]

        # Check the core equation: n = ab + ac + bc
        calculated_n = a * b + a * c + b * c

        if calculated_n == n:
            tau_n = len(divs)
            solutions[n] = tau_n
            print(f"Solution found: n={n}, divisors={divs}, a={a}, b={b}, c={c}. Check: {calculated_n} = {n}. Tau(n) = {tau_n}")

    print("\n--- Search Complete ---")
    print("All solutions found (n, tau(n)):")
    for n, tau in solutions.items():
        print(f"n={n}, tau(n)={tau}")

    # Report specifically on tau(n) != 8 and tau(n) != 9
    other_tau = {n: tau for n, tau in solutions.items() if tau not in [8, 9]}
    if other_tau:
        print("\n--- Solutions where tau(n) is NOT 8 or 9 ---")
        for n, tau in other_tau.items():
            print(f"n={n}, tau(n)={tau}")
    else:
        print("\nNo solutions found where tau(n) is not 8 or 9.")

solve_problem(N_max=1000)
